import {GitHubAvatar} from '@github-ui/github-avatar'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {Button, Heading, Link, Stack} from '@primer/react'
import React from 'react'

import {SettingsMenu} from './SettingsMenu'
import styles from './SsoOrgsSettingsList.module.css'

interface SsoOrg {
  id: number
  login: string
  profile_name?: string
  primary_avatar_url?: string
  dismissed?: boolean
  needs_authentication?: boolean
  sso_url?: string
  sso_url_logout?: string
  signing_out?: boolean
}

export interface SsoOrgsSettingsListProps {
  ssoOrgs: SsoOrg[]
}

export function SsoOrgsSettingsList({ssoOrgs}: SsoOrgsSettingsListProps) {
  const [orgsState, setOrgsState] = React.useState(ssoOrgs)

  const updateOrgState = React.useCallback((orgId: number, updates: Partial<SsoOrg>) => {
    setOrgsState(prevOrgs => prevOrgs.map(prevOrg => (prevOrg.id === orgId ? {...prevOrg, ...updates} : prevOrg)))
  }, [])

  const handleCookieReset = React.useCallback(() => {
    setOrgsState(prevOrgs =>
      prevOrgs.map(org => ({
        ...org,
        dismissed: false,
      })),
    )
  }, [])

  const handleSignOut = React.useCallback(
    async (org: SsoOrg) => {
      if (!org.sso_url_logout || org.signing_out) return

      updateOrgState(org.id, {signing_out: true})

      try {
        const formData = new FormData()

        const response = await verifiedFetch(org.sso_url_logout, {
          method: 'DELETE',
          body: formData,
        })

        if (response.ok) {
          updateOrgState(org.id, {needs_authentication: true, signing_out: false})
        } else {
          updateOrgState(org.id, {signing_out: false})
        }
      } catch {
        updateOrgState(org.id, {signing_out: false})
      }
    },
    [updateOrgState],
  )

  const hasDismissedOrgs = orgsState.some(org => org.dismissed)

  return (
    <>
      <Stack direction="horizontal" justify="space-between">
        <Heading as="h2" className={styles.heading}>
          Single sign-on
        </Heading>
        {hasDismissedOrgs && <SettingsMenu onCookieReset={handleCookieReset} />}
      </Stack>

      <div className={styles.container}>
        {orgsState.map(org => (
          <div key={org.id} className={styles.orgRow} data-testid={`sso-org-row-${org.id}`}>
            {org.primary_avatar_url && (
              <GitHubAvatar src={org.primary_avatar_url} size={20} alt={org.login} className={styles.avatar} />
            )}

            <div className={styles.content}>
              <Link href={`/${org.login}`} className={styles.orgLink} data-testid={`sso-org-link-${org.id}`}>
                {org.login}
              </Link>
              {org.profile_name && <span className={styles.profileName}>{org.profile_name}</span>}
            </div>

            {org.dismissed && <span className={styles.dismissedText}>Dismissed</span>}

            {org.needs_authentication ? (
              <Button variant="default" size="small" as="a" href={org.sso_url}>
                Sign in
              </Button>
            ) : (
              <Button variant="danger" size="small" onClick={() => handleSignOut(org)} loading={org.signing_out}>
                Sign out
              </Button>
            )}
          </div>
        ))}
      </div>
    </>
  )
}

try{ SsoOrgsSettingsList.displayName ||= 'SsoOrgsSettingsList' } catch {}